// FreeRTOS configuration for LP_CC1312R7 + Pigweed.
//
// The base settings are generated by TI SysConfig (tools/syscfg_gen.py writes
// syscfg_gen/ti_syscfg_FreeRTOSConfig.h). This wrapper layers on the settings
// Pigweed's FreeRTOS backends need, so regenerating SysConfig never loses them.
#pragma once

#include "ti_syscfg_FreeRTOSConfig.h"

// Route FreeRTOS asserts through pw_assert (prints file/line over UART).
#ifndef __IAR_SYSTEMS_ASM__
#include "pw_third_party/freertos/config_assert.h"
#endif

// pw_thread_freertos: Thread::join() support and thread iteration.
#undef INCLUDE_vTaskSuspend
#define INCLUDE_vTaskSuspend 1
#undef INCLUDE_uxTaskGetStackHighWaterMark
#define INCLUDE_uxTaskGetStackHighWaterMark 1

// Pigweed's //third_party/freertos:support supplies the idle/timer task
// memory callbacks; TI's StaticAllocs_freertos.c is excluded from the build.
